-- Academy: rebuild Yachts Module 3 as "The Yacht Market": 15 pages (8 with quick checks, 7 with answerable exercises
-- saved to the Broker Portfolio) + a 7-question final quiz. Same shape as the Module 1 migration.

do $mig$
declare
  v_module uuid;
  v_q uuid;
  v_page uuid;
  rec jsonb;
  n int := 0;
  i int;
  v_pages jsonb := $json$[{"heading": "The Yacht Market: How Does This Business Actually Work?", "body": "<p>You now know how to look at a yacht.</p><p>You can recognise the major yacht types. You understand that two yachts of the same length can be completely different. You have started thinking about purpose, condition, ownership, operating reality and client fit.</p><p>Now comes the next question:</p><p><b>How does a yacht become a business opportunity?</b></p><p>Why is one yacht worth €4 million and another €7 million? Why would someone build a brand-new yacht instead of buying an existing one? Why does a yacht that looked attractive six months ago suddenly become difficult to sell? Why can two similar yachts have very different asking prices?</p><p>And perhaps most importantly: <b>how does a broker decide whether a yacht is actually worth presenting to a client?</b></p><p>This is where you begin to move from <b>looking at yachts</b> to <b>thinking about the market.</b></p><p>You do not need to become a professional valuer. You do not need to memorise every shipyard, designer or model. You do need to understand the forces that influence a yacht's value, desirability and saleability.</p><p>Because a broker who understands the market can do something much more valuable than simply show yachts.</p><p><b>They can explain why one opportunity deserves attention.</b></p>", "q": "What does understanding the market allow a broker to do that is more valuable than simply showing yachts?", "opts": ["Memorise every shipyard, designer and model", "Act as a professional valuer", "Explain why one opportunity deserves attention", "Always find the cheapest yacht available"], "correct": 2}, {"heading": "Chapter 1: New Build vs Brokerage", "body": "<p><b>Why would someone buy a new yacht?</b></p><p>Imagine you have a client with €15 million available. You find two possibilities. One is a five-year-old yacht that is beautifully maintained, immediately available and already proven. The other is a new build that will not be delivered for three years.</p><p>Why would anyone choose the second option?</p><p>Because buying a yacht is not simply buying an object. It is choosing a combination of design, timing, customisation, technology, condition, reputation, operating profile, availability, financial commitment and personal preference.</p><p>A new build offers something a brokerage yacht cannot: <b>the ability to influence what the yacht becomes.</b> The owner may have input into layout, materials, interior, exterior spaces, technical systems, cabins, tenders and equipment. But that freedom comes with time, complexity and risk.</p><p>A brokerage yacht offers something different: <b>certainty about what already exists.</b> You can inspect it, survey it, speak to the crew, examine its history, see how the spaces work, and potentially buy it and use it much sooner.</p><p>Neither route is automatically better. The right choice depends on the client.</p><p><b>A simple comparison</b></p><p>&bull; Delivery: new build is in the future; brokerage is usually immediate or relatively soon<br/>&bull; Customisation: new build is high; brokerage is limited to modifications<br/>&bull; History: new build has limited history during construction; brokerage has an existing history<br/>&bull; Condition: new build is new; brokerage varies<br/>&bull; Depreciation: an important consideration for a new build; already established for brokerage<br/>&bull; Decision process: new build is long and complex; brokerage is usually faster<br/>&bull; Risk: new build carries construction, timing and specification risk; brokerage carries condition, history and valuation risk<br/>&bull; Relationship: new build is with the shipyard and project team; brokerage is with the seller, broker and technical team</p><p>The professional question is not \"which is better?\" It is: <b>\"which makes sense for this client?\"</b></p><p><b>Why this matters to a broker</b></p><p>A client may begin by saying: <em>\"I want a brand-new 40-metre yacht.\"</em> That sounds like a requirement. It may actually be a preference. Once you ask questions, you may discover they want to cruise next summer, dislike long construction projects, want proven crew arrangements, are happy to compromise on interior design, or care more about outdoor space than newness.</p><p>Suddenly, a brokerage yacht may deserve serious consideration. The broker's job is not to defend the client's first statement. It is to understand the reason behind it.</p><p><b>Broker's insight</b></p><p><b>The client's stated requirement is often the beginning of the conversation, not the end of it.</b></p>", "q": "A client says, \"I want a brand-new 40-metre yacht.\" What should a broker do first?", "opts": ["Ask questions to understand the reason behind the statement, since it may be a preference rather than a requirement", "Agree and start searching only for new builds", "Steer the client toward a brokerage yacht immediately", "Explain that new builds are always riskier"], "correct": 0}, {"heading": "Exercise: New Build or Brokerage?", "body": "<p><b>New build or brokerage?</b></p><p>A client says:</p><p><em>\"I want a brand-new yacht because I don't want someone else's problems.\"</em></p><p>Write down <b>five questions</b> you would ask before agreeing that new build is the right route. Then identify what each question is trying to discover.</p><p>Then, a short reflection: which appeals to you more at this stage? There is no correct answer. You are beginning to discover which parts of the business interest you.</p>", "exercise": {"intro": "Five questions you would ask, and what each is trying to discover.", "groups": [{"title": "My five questions", "section": "services", "fields": [{"key": "nb_q1", "label": "Question 1", "type": "short", "min": 10}, {"key": "nb_w1", "label": "What question 1 is trying to discover", "type": "short", "min": 10}, {"key": "nb_q2", "label": "Question 2", "type": "short", "min": 10}, {"key": "nb_w2", "label": "What question 2 is trying to discover", "type": "short", "min": 10}, {"key": "nb_q3", "label": "Question 3", "type": "short", "min": 10}, {"key": "nb_w3", "label": "What question 3 is trying to discover", "type": "short", "min": 10}, {"key": "nb_q4", "label": "Question 4", "type": "short", "min": 10}, {"key": "nb_w4", "label": "What question 4 is trying to discover", "type": "short", "min": 10}, {"key": "nb_q5", "label": "Question 5", "type": "short", "min": 10}, {"key": "nb_w5", "label": "What question 5 is trying to discover", "type": "short", "min": 10}]}, {"title": "Broker reflection", "section": "profile", "fields": [{"key": "nb_appeal", "label": "Which appeals to you more at this stage?", "type": "choice", "options": ["The creative process of a new build", "The research and evaluation of buying an existing yacht", "Both", "Neither yet"]}, {"key": "nb_why", "label": "Why?", "type": "long", "min": 15}]}]}}, {"heading": "Chapter 2: The Builders and Designers", "body": "<p><b>Who actually creates a yacht?</b></p><p>A yacht is rarely the product of one company or one person. Behind a finished yacht is an enormous chain of expertise. Depending on the project, you may encounter shipyards, naval architects, exterior designers, interior designers, engineering teams, project managers, subcontractors, equipment manufacturers, classification organisations, flag authorities, specialist consultants, surveyors and brokers.</p><p>For a beginner, the names can feel overwhelming. Do not try to memorise them all. Instead, understand the basic distinction between <b>who builds</b>, <b>who designs</b>, and <b>who verifies</b>.</p><p><b>Shipyards</b></p><p>The shipyard is responsible for constructing the yacht. Different shipyards develop different reputations, capabilities and areas of specialisation. Some are known for large custom yachts, series production, explorer yachts, sailing yachts, high-performance yachts, refit work or complex technical projects.</p><p>A shipyard's reputation can influence how the market perceives a yacht. But reputation alone does not determine value. A famous builder does not automatically make every individual yacht the right opportunity.</p><p><b>Designers</b></p><p>A yacht may involve several design disciplines. The <b>exterior designer</b> influences the yacht's visual identity and external architecture. The <b>interior designer</b> shapes the experience inside. The <b>naval architect</b> works on the yacht's underlying design and performance characteristics. Sometimes one studio is responsible for several elements; sometimes different specialists are involved.</p><p>For a broker, the important question is not \"can I explain naval architecture?\" It is: <b>\"can I understand what the design choices mean for the client?\"</b></p><p><b>Design creates consequences</b></p><p>A dramatic exterior may create excellent visual appeal. A large beach club may create an exceptional guest experience. A shallow draft may open cruising possibilities. A huge interior volume may create impressive accommodation. A high-performance hull may deliver speed. But every design decision involves trade-offs.</p><p>That is one of the most important concepts in yacht brokerage: <b>there is rarely a perfect yacht.</b> There are yachts that are particularly well suited to particular owners.</p><p><b>Broker's insight</b></p><p><b>A yacht's design tells you something about the life its owner imagined living aboard it.</b> Your job is to connect that intention to the client's reality.</p>", "q": "What basic distinction should a beginner understand about the chain of expertise behind a yacht?", "opts": ["Who owns, who charters, and who crews", "Who sells, who buys, and who finances", "Who names, who paints, and who launches", "Who builds, who designs, and who verifies"], "correct": 3}, {"heading": "Exercise: See It — Three Yachts, Three Designs", "body": "<p><b>See it</b></p><p>Choose <b>three yachts of broadly similar size.</b> Research the builder, exterior designer, interior designer, year, approximate asking price and cruising profile.</p><p>Then compare how differently the yachts have been designed. Do not decide which is \"best.\" Ask: <b>what kind of owner does each yacht seem designed for?</b></p>", "exercise": {"intro": "Pick three yachts of broadly similar size. Write 'Need to verify' only if a listing genuinely doesn't say.", "groups": [{"title": "Yacht 1", "section": "market", "fields": [{"key": "s1_name", "label": "Yacht 1: name", "type": "short", "min": 3}, {"key": "s1_builder", "label": "Yacht 1: builder", "type": "short", "min": 3}, {"key": "s1_ext", "label": "Yacht 1: exterior designer", "type": "short", "min": 3}, {"key": "s1_int", "label": "Yacht 1: interior designer", "type": "short", "min": 3}, {"key": "s1_year", "label": "Yacht 1: year and approximate asking price", "type": "short", "min": 6}, {"key": "s1_profile", "label": "Yacht 1: cruising profile", "type": "short", "min": 5}, {"key": "s1_owner", "label": "What kind of owner does Yacht 1 seem designed for?", "type": "long", "min": 20}]}, {"title": "Yacht 2", "section": "market", "fields": [{"key": "s2_name", "label": "Yacht 2: name", "type": "short", "min": 3}, {"key": "s2_builder", "label": "Yacht 2: builder", "type": "short", "min": 3}, {"key": "s2_ext", "label": "Yacht 2: exterior designer", "type": "short", "min": 3}, {"key": "s2_int", "label": "Yacht 2: interior designer", "type": "short", "min": 3}, {"key": "s2_year", "label": "Yacht 2: year and approximate asking price", "type": "short", "min": 6}, {"key": "s2_profile", "label": "Yacht 2: cruising profile", "type": "short", "min": 5}, {"key": "s2_owner", "label": "What kind of owner does Yacht 2 seem designed for?", "type": "long", "min": 20}]}, {"title": "Yacht 3", "section": "market", "fields": [{"key": "s3_name", "label": "Yacht 3: name", "type": "short", "min": 3}, {"key": "s3_builder", "label": "Yacht 3: builder", "type": "short", "min": 3}, {"key": "s3_ext", "label": "Yacht 3: exterior designer", "type": "short", "min": 3}, {"key": "s3_int", "label": "Yacht 3: interior designer", "type": "short", "min": 3}, {"key": "s3_year", "label": "Yacht 3: year and approximate asking price", "type": "short", "min": 6}, {"key": "s3_profile", "label": "Yacht 3: cruising profile", "type": "short", "min": 5}, {"key": "s3_owner", "label": "What kind of owner does Yacht 3 seem designed for?", "type": "long", "min": 20}]}]}}, {"heading": "Chapter 3: Why People Buy Yachts", "body": "<p><b>There is no single yacht buyer</b></p><p>One of the easiest mistakes for a new broker is assuming that people buy yachts for the same reason. They do not.</p><p>One owner may want family time. Another may want adventure. Another may entertain extensively. Another may want privacy. Another may want to cruise remote destinations. Another may care deeply about design, or almost entirely about performance. Another may simply want the experience of owning a yacht.</p><p>The yacht is the product. <b>The motivation is the business.</b></p><p><b>Common purchase motivations</b></p><p>&bull; <b>Lifestyle:</b> they want to spend more time with family or friends<br/>&bull; <b>Adventure:</b> they want access to destinations that are difficult to experience conventionally<br/>&bull; <b>Entertainment:</b> they want to host guests, events and business relationships<br/>&bull; <b>Privacy:</b> they value control over their environment and travel<br/>&bull; <b>Status:</b> ownership can carry social or personal significance<br/>&bull; <b>Passion:</b> some owners genuinely love yachts, boats, design or the sea<br/>&bull; <b>Exploration:</b> the yacht may be designed around long-range or remote cruising<br/>&bull; <b>Customisation:</b> the owner wants a vessel that reflects their precise preferences<br/>&bull; <b>Experience:</b> they want the freedom and flexibility that comes with private yacht ownership</p><p>Often several motivations exist simultaneously.</p><p><b>The deeper question</b></p><p>A weak broker asks: <em>\"What size yacht do you want?\"</em></p><p>A stronger broker eventually asks: <b>\"What do you want your life with the yacht to look like?\"</b></p><p>That question changes the conversation. A 30-metre yacht can be enormous for one family and completely inadequate for another. A fast yacht can be perfect for one owner and irrelevant to another. A six-cabin yacht may be essential for one client and unnecessary complexity for another.</p><p>This is why yacht brokerage is fundamentally connected to lifestyle.</p>", "q": "Which question separates a stronger broker from a weak one?", "opts": ["\"What size yacht do you want?\"", "\"What do you want your life with the yacht to look like?\"", "\"What is your maximum budget?\"", "\"How soon can you decide?\""], "correct": 1}, {"heading": "Exercise: Needs Before Products", "body": "<p><b>Try it</b></p><p>Imagine three hypothetical clients.</p><p><b>Client A:</b> a couple with young children who want Mediterranean summers.</p><p><b>Client B:</b> a group of friends who want to entertain and travel quickly between destinations.</p><p><b>Client C:</b> an experienced owner who wants to explore remote areas for several months at a time.</p><p>For each, write what they might value most, what yacht characteristics might matter, and what they might be willing to compromise on. You are not choosing yachts yet. You are learning to think about <b>needs before products.</b></p>", "exercise": {"intro": "Three clients, three sets of needs. No yachts yet.", "groups": [{"title": "Client A", "section": "services", "fields": [{"key": "ca_value", "label": "Client A: what might they value most?", "type": "long", "min": 20}, {"key": "ca_chars", "label": "Client A: what yacht characteristics might matter?", "type": "long", "min": 20}, {"key": "ca_comp", "label": "Client A: what might they be willing to compromise on?", "type": "long", "min": 20}]}, {"title": "Client B", "section": "services", "fields": [{"key": "cb_value", "label": "Client B: what might they value most?", "type": "long", "min": 20}, {"key": "cb_chars", "label": "Client B: what yacht characteristics might matter?", "type": "long", "min": 20}, {"key": "cb_comp", "label": "Client B: what might they be willing to compromise on?", "type": "long", "min": 20}]}, {"title": "Client C", "section": "services", "fields": [{"key": "cc_value", "label": "Client C: what might they value most?", "type": "long", "min": 20}, {"key": "cc_chars", "label": "Client C: what yacht characteristics might matter?", "type": "long", "min": 20}, {"key": "cc_comp", "label": "Client C: what might they be willing to compromise on?", "type": "long", "min": 20}]}]}}, {"heading": "Chapter 4: Why People Sell Yachts", "body": "<p><b>The other side of the market</b></p><p>Every buyer opportunity begins with a seller. And sellers have motivations too. A yacht may come onto the market because the owner's circumstances have changed, the family has grown or changed, the owner wants a larger or smaller yacht, the yacht is no longer being used enough, the owner wants a different type of yacht, operating costs have become unattractive, a new build is being delivered, or the owner has simply decided to move on.</p><p>Sometimes the reason is straightforward. Sometimes it is complicated. And sometimes the broker will never know the complete personal story. That is where professionalism matters.</p><p><b>The seller's perspective</b></p><p>Imagine owning a yacht for eight years. It contains memories. You selected the furniture. You chose the paint. You know the captain. You have spent summers aboard. You may have invested millions in maintenance and improvements.</p><p>Now a broker tells you: <em>\"The market doesn't value the yacht as highly as you do.\"</em></p><p>That conversation requires much more than sales technique. It requires evidence, tact, preparation, credibility, honesty and emotional intelligence. The seller may disagree. The broker still has a responsibility to explain the market clearly.</p><p><b>Why yachts stay on the market</b></p><p>A yacht can remain unsold for many reasons: an unrealistic asking price, poor presentation, the wrong buyers being targeted, a specification that limits demand, a changed market, competing yachts, technical or historical concerns, a seller unwilling to negotiate, or simply not being the right opportunity for current buyers.</p><p>A long time on the market does not automatically mean a yacht is bad. It does mean the broker should investigate.</p><p><b>Broker's insight</b></p><p><b>A yacht's story matters.</b> Before presenting an opportunity, learn:</p><p>&bull; Why is it for sale?<br/>&bull; How long has it been for sale?<br/>&bull; What has changed?<br/>&bull; What has been invested in it?<br/>&bull; What are buyers comparing it against?<br/>&bull; What could make the transaction difficult?</p><p>Good brokerage is rarely about knowing only the attractive facts. It is about understanding the whole picture.</p>", "q": "A yacht has been on the market for a long time. What does that tell you?", "opts": ["That it must have serious technical faults", "That the asking price is definitely too low", "Not automatically that it is a bad yacht, but that the broker should investigate why", "That the seller is not serious"], "correct": 2}, {"heading": "Chapter 5: What Makes a Yacht Valuable?", "body": "<p><b>Price is not the same as value</b></p><p><b>Price</b> is the amount someone is asking. <b>Value</b> is what the market may reasonably support. They are not always the same.</p><p>A yacht listed at €10 million is not automatically worth €10 million. Likewise, a yacht listed at €10 million may represent an attractive opportunity if the market evidence supports a higher underlying value. The broker's job is to understand the difference.</p><p><b>What influences yacht value?</b></p><p>There is no single formula. Important factors can include:</p><p>&bull; <b>Age:</b> newer yachts often appeal to buyers seeking modern design and reduced immediate renewal requirements, but age alone does not determine value<br/>&bull; <b>Builder:</b> reputation can influence desirability, perceived quality and resale confidence<br/>&bull; <b>Design:</b> affects appearance, layout, usability and market appeal<br/>&bull; <b>Condition:</b> maintenance, refits and technical condition can significantly affect buyer perception<br/>&bull; <b>Specification:</b> equipment, amenities, tenders, toys, technology and interior specification<br/>&bull; <b>Maintenance history:</b> a well-documented history can reduce uncertainty<br/>&bull; <b>Usage:</b> private use, charter use, cruising patterns and operating history may all influence a buyer's assessment<br/>&bull; <b>Location:</b> current location and cruising region can affect accessibility and transaction logistics<br/>&bull; <b>Market supply:</b> if many similar yachts are available, buyers have more alternatives<br/>&bull; <b>Market demand:</b> if several buyers are competing for a particular type of yacht, the dynamics can change<br/>&bull; <b>Ownership and transaction structure:</b> legal and commercial circumstances can also affect a transaction</p><p><b>The most important concept: comparison</b></p><p>A broker rarely asks <em>\"what do I think this yacht is worth?\"</em> The better question is: <b>\"what are comparable yachts telling us?\"</b></p><p>That means looking at similar length, age, builder, design, condition, specification, cruising profile and market positioning. Then you investigate the differences.</p><p><b>Asking price is evidence, not truth</b></p><p>Imagine three comparable yachts:</p><p>&bull; A: KING POWER, 35.2m, 2016, €8.80m<br/>&bull; B: NAYA 7, 34.1m, 2016, €7.29m<br/>&bull; C: Azimut Grande 35M, 34.64m, 2017, €7.95m</p><p>These are not interchangeable. <b>KING POWER</b> is a 2016 Sunseeker 116, privately operated from new, with five cabins, accommodation for 10 guests and a published maximum speed of 26 knots. <b>NAYA 7</b> is a 2016 Sanlorenzo SD112, refitted in 2024, with five cabins, accommodation for 10 guests and a published maximum speed of 18 knots, and a published asking price of €7.29 million. The <b>Azimut Grande 35M</b> is a 2017 yacht with five cabins, 10 berths, twin MTU engines and a published asking price of €7.95 million.</p><p>A beginner might simply compare the prices. A broker asks: <b>why are they different?</b> Perhaps one has a different hull and performance profile, has been refitted, has particularly low private-use hours, has different exterior spaces or interior design, has a different builder reputation, has different VAT or ownership circumstances, or may require different levels of future expenditure.</p><p>The numbers become meaningful only when you understand the reasons behind them.</p><p><b>A note on valuation</b></p><p>Professional yacht valuation can involve specialist methodologies, detailed inspection and market evidence. This academy is not asking you to become a professional valuer. You are learning the broker's first level of market analysis:</p><p><b>compare → investigate → question → interpret → communicate.</b></p>", "q": "What is the difference between price and value?", "opts": ["Price is what someone is asking; value is what the market may reasonably support", "They are the same once a yacht is listed", "Price is set by the buyer; value is set by the seller", "Value is always higher than price"], "correct": 0}, {"heading": "Chapter 6: Your First Market Analysis", "body": "<p>Now it is time to use what you have learned. You are going to analyse a small group of yachts as a broker might before presenting them to a client.</p><p><b>The scenario</b></p><p>Your client wants a yacht for Mediterranean family cruising. Their initial requirements:</p><p>&bull; approximately 30-40 metres<br/>&bull; comfortable for family use<br/>&bull; good outdoor spaces<br/>&bull; suitable for summer cruising<br/>&bull; attractive but not excessively formal<br/>&bull; reasonable crew requirements<br/>&bull; budget around €8 million</p><p>You have found three real market examples. Your task is <b>not</b> to decide which yacht is \"best.\" Your task is to understand the market.</p><p><b>Yacht A: KING POWER</b></p><p>&bull; Sunseeker 116 Yacht, 2016, 35.2m, 7.34m beam, 245 GT<br/>&bull; Asking price: €8.80 million<br/>&bull; 10 guests, 5 cabins, 3 crew listed<br/>&bull; Cruising 12 knots, maximum 26 knots<br/>&bull; 2 x MTU 16V 2000 M96L, deep-V GRP hull<br/>&bull; Antibes, France<br/>&bull; Privately run from new; never in charter according to the listing<br/>&bull; The listing highlights low engine hours and long-standing crew</p><p><b>Yacht B: NAYA 7</b></p><p>&bull; Sanlorenzo SD112, 2016, refit 2024, 34.1m, 7.66m beam, 266 GT<br/>&bull; Asking price: €7.29 million<br/>&bull; 10 guests, 5 cabins<br/>&bull; Cruising 10 knots, maximum 18 knots<br/>&bull; 2 x MTU 10V2000M93<br/>&bull; Cannes, France<br/>&bull; Privately used according to the listing<br/>&bull; The listing highlights recent upgrades including new paint and states that VAT is paid</p><p><b>Yacht C: AZIMUT GRANDE 35M</b></p><p>&bull; Azimut Grande 35M, 2017, 34.64m, 7.50m beam, gross tonnage not specified in the selected listing<br/>&bull; Asking price: €7.95 million<br/>&bull; 10 guests, 5 cabins<br/>&bull; 2 x MTU 16V2000, approximately 1,620 engine hours listed<br/>&bull; Cruising 18 knots, maximum 25.5 knots<br/>&bull; 2 x 55kW Kohler generators, zero-speed stabilisers<br/>&bull; Location: France<br/>&bull; The listing highlights a sky deck, a large aft beach-club area and a lateral tender garage</p><p><b>Broker's note:</b> these figures are published listing information gathered for training. Listings can change, and advertised specifications should always be independently verified before being relied upon in a real transaction.</p>", "q": "In this scenario, what is your task?", "opts": ["To choose the cheapest yacht", "To negotiate the lowest price for the client", "To confirm the listings are accurate", "To understand the market, not to decide which yacht is \"best\""], "correct": 3}, {"heading": "Steps 1 and 2: Collect the Facts, Look Beyond the Numbers", "body": "<p><b>Step 1: collect the facts</b></p><p>Create a broker's comparison sheet using the information on the previous page: name, builder, model, year, length, beam, gross tonnage, asking price, engine, cruising and maximum speed, cabins, guest capacity, crew information, location, private or charter history, refit history, major features, and information requiring verification.</p><p>Do not fill gaps with assumptions. If you do not know something, write <b>\"Need to verify.\"</b> That is a professional habit.</p><p><b>Step 2: look beyond the numbers</b></p><p>For each yacht, answer: what appears attractive, what might require investigation, what information is missing, and what you would want to verify before showing the yacht to the client. This is where you begin developing the broker's instinct.</p>", "exercise": {"intro": "One sheet per yacht. Don't fill gaps with assumptions.", "groups": [{"title": "KING POWER", "section": "yachts", "fields": [{"key": "ka_facts", "label": "KING POWER: facts collected (name, builder, model, year, length, beam, GT, price, engines, speeds, cabins, guests, crew, location, usage, refit, features). Write \"Need to verify\" for anything unknown.", "type": "long", "min": 80}, {"key": "ka_attr", "label": "KING POWER: what appears attractive?", "type": "long", "min": 20}, {"key": "ka_inv", "label": "KING POWER: what might require investigation?", "type": "long", "min": 20}, {"key": "ka_miss", "label": "KING POWER: what information is missing?", "type": "long", "min": 15}, {"key": "ka_verify", "label": "KING POWER: what would you verify before showing it to the client?", "type": "long", "min": 20}]}, {"title": "NAYA 7", "section": "yachts", "fields": [{"key": "nb_facts", "label": "NAYA 7: facts collected (name, builder, model, year, length, beam, GT, price, engines, speeds, cabins, guests, crew, location, usage, refit, features). Write \"Need to verify\" for anything unknown.", "type": "long", "min": 80}, {"key": "nb_attr", "label": "NAYA 7: what appears attractive?", "type": "long", "min": 20}, {"key": "nb_inv", "label": "NAYA 7: what might require investigation?", "type": "long", "min": 20}, {"key": "nb_miss", "label": "NAYA 7: what information is missing?", "type": "long", "min": 15}, {"key": "nb_verify", "label": "NAYA 7: what would you verify before showing it to the client?", "type": "long", "min": 20}]}, {"title": "AZIMUT GRANDE 35M", "section": "yachts", "fields": [{"key": "az_facts", "label": "AZIMUT GRANDE 35M: facts collected (name, builder, model, year, length, beam, GT, price, engines, speeds, cabins, guests, crew, location, usage, refit, features). Write \"Need to verify\" for anything unknown.", "type": "long", "min": 80}, {"key": "az_attr", "label": "AZIMUT GRANDE 35M: what appears attractive?", "type": "long", "min": 20}, {"key": "az_inv", "label": "AZIMUT GRANDE 35M: what might require investigation?", "type": "long", "min": 20}, {"key": "az_miss", "label": "AZIMUT GRANDE 35M: what information is missing?", "type": "long", "min": 15}, {"key": "az_verify", "label": "AZIMUT GRANDE 35M: what would you verify before showing it to the client?", "type": "long", "min": 20}]}]}}, {"heading": "Steps 3 and 4: Compare and Write Your Market View", "body": "<p><b>Step 3: compare</b></p><p>Create a simple comparison of the three yachts: year, length, asking price, builder, design and profile, cabins, guests, speeds, refit and upgrades, usage, location, potential attraction, questions to investigate and information requiring verification.</p><p>The published data show why a simple price comparison is not enough. The three yachts are close in length and all offer five cabins for 10 guests, but they differ in design, performance, history, published usage information and asking price.</p><p><b>Step 4: write your market view</b></p><p>Write approximately 200 words answering: <b>\"What does this small group of yachts tell me about the current market?\"</b> You might discuss price differences, age versus price, specification, condition, builder reputation, performance, availability, client fit, obvious compromises and missing information.</p><p>Do not write a sales pitch. Write an observation.</p>", "exercise": {"intro": "Compare, then write your market view.", "groups": [{"title": "My comparison", "section": "market", "fields": [{"key": "cmp_ka", "label": "KING POWER: how it compares (year, price, builder, profile, speeds, refit, usage, location, attractions, questions)", "type": "long", "min": 60}, {"key": "cmp_nb", "label": "NAYA 7: how it compares", "type": "long", "min": 60}, {"key": "cmp_az", "label": "AZIMUT GRANDE 35M: how it compares", "type": "long", "min": 60}]}, {"title": "Similarities, differences, prices", "section": "market", "fields": [{"key": "cmp_sim", "label": "Key similarities", "type": "long", "min": 30}, {"key": "cmp_diff", "label": "Key differences", "type": "long", "min": 30}, {"key": "cmp_price", "label": "Pricing observations", "type": "long", "min": 30}, {"key": "cmp_q", "label": "Questions requiring investigation", "type": "long", "min": 30}]}, {"title": "My market view", "section": "market", "fields": [{"key": "market_view", "label": "What does this small group of yachts tell me about the current market? (about 200 words; an observation, not a sales pitch)", "type": "long", "min": 700}]}]}}, {"heading": "Broker Challenge: The Client Who Likes the Photographs", "body": "<p><b>Broker challenge</b></p><p>Your client calls you. They say:</p><p><em>\"I like Yacht A because it looks the nicest in the photographs. Let's buy that one.\"</em></p><p>You have not yet completed your investigation. What do you say?</p><p>Write your response as though you are speaking directly to the client. Your goal is to be helpful without pretending to know more than you do.</p><p>A strong response should demonstrate confidence without arrogance, enthusiasm without pressure, evidence rather than opinion, curiosity, willingness to investigate, and protection of the client's interests.</p>", "exercise": {"intro": "Speak directly to the client.", "groups": [{"title": "My response to the client", "section": "services", "fields": [{"key": "client_reply", "label": "What do you say?", "type": "long", "min": 300, "placeholder": "Thank you for telling me which one caught your eye..."}]}]}}, {"heading": "Reflection and Broker's Notebook", "body": "<p><b>Reflection</b></p><p>You have now moved through three different ways of looking at a yacht.</p><p><b>Module 1:</b> what is this world? <b>Module 2:</b> what is this yacht? <b>Module 3:</b> why does this yacht matter in the market?</p><p>There is no need to have a career answer yet. You are collecting evidence.</p><p><b>Broker's notebook</b></p><p>Before leaving this module, make sure you can explain these concepts in your own words:</p><p>&bull; new build<br/>&bull; brokerage yacht<br/>&bull; shipyard<br/>&bull; naval architect<br/>&bull; exterior designer<br/>&bull; interior designer<br/>&bull; buyer motivation<br/>&bull; seller motivation<br/>&bull; asking price<br/>&bull; market value<br/>&bull; comparable yacht<br/>&bull; market supply<br/>&bull; market demand<br/>&bull; refit<br/>&bull; specification<br/>&bull; market analysis</p>", "exercise": {"intro": "Answer honestly. You are collecting evidence, not making a career decision.", "groups": [{"title": "What I noticed", "section": "profile", "fields": [{"key": "m_enjoy_compare", "label": "Did I enjoy comparing yachts?", "type": "short", "min": 10}, {"key": "m_enjoy_research", "label": "Did I enjoy researching the details?", "type": "short", "min": 10}, {"key": "m_commercial", "label": "Did the commercial side interest me?", "type": "short", "min": 10}, {"key": "m_prices", "label": "Did I enjoy trying to understand why prices differ?", "type": "short", "min": 10}, {"key": "m_questions", "label": "Did I find myself naturally asking questions?", "type": "short", "min": 10}, {"key": "m_people", "label": "Did I prefer the people side of brokerage?", "type": "short", "min": 10}, {"key": "m_product", "label": "Did I prefer the product and market side?", "type": "short", "min": 10}, {"key": "m_next", "label": "What would I like to understand next?", "type": "short", "min": 10}]}]}}, {"heading": "Professional Output, Final Reflection and What Comes Next", "body": "<p><b>Professional output: my first market analysis</b></p><p>Your answers from this module are saved to your <b>Broker Portfolio</b>: the three yachts you researched, your comparisons, key similarities and differences, pricing observations, questions requiring investigation, your 200-word market view and your response to the client.</p><p>This is your first piece of work that begins to look like something a junior broker might actually produce. Do not worry about making it perfect. The objective is to demonstrate a professional habit:</p><p><b>Look carefully. Compare intelligently. Question what you do not know.</b></p><p><b>Final reflection</b></p><p>At the beginning of this module, the yacht was an object. Now you should be starting to see something more complicated. A yacht sits inside a market. Its price has a story. Its design has a purpose. Its owner has motivations. Its seller has motivations. Its competitors matter. Its history matters. Its condition matters. And the client's needs determine whether any of those things actually make it the right opportunity.</p><p>That is the beginning of commercial thinking. You do not yet need to know exactly what a yacht is worth. You need to become comfortable asking:</p><p>&bull; \"Compared with what?\"<br/>&bull; \"Why?\"<br/>&bull; \"For whom?\"<br/>&bull; \"What are we missing?\"</p><p>Those four questions will take you a long way.</p><p><b>What comes next</b></p><p>You now understand the yacht and the market around it. Next, we turn to the person at the centre of the transaction.</p><p><b>Module 4: The People and the Client.</b> Yacht brokerage is a people business. You will learn who actually buys yachts, how experienced brokers discover what clients really want, how lifestyle becomes yacht requirements, why trust and discretion matter, how to build a professional client profile, and how to approach your first client conversation.</p><p>Because ultimately, the broker's job is not to find <b>a yacht.</b> It is to find <b>the right yacht for the right person.</b></p>", "q": "Which four questions does this module say will take you a long way?", "opts": ["\"How much? How soon? How big? How fast?\"", "\"Compared with what? Why? For whom? What are we missing?\"", "\"Who built it? Who owns it? Who sold it? Who paid?\"", "\"Is it new? Is it fast? Is it cheap? Is it famous?\""], "correct": 1}]$json$;
  v_final jsonb := $json$[{"q": "What is one major difference between a new build and a brokerage yacht?", "opts": ["A new build can be inspected before purchase; a brokerage yacht cannot", "A brokerage yacht can be fully customised; a new build cannot", "A new build can be highly customised but takes time; a brokerage yacht already exists, can be inspected, and can potentially be acquired sooner", "There is no meaningful difference beyond price"], "correct": 2}, {"q": "Why does a shipyard's reputation matter?", "opts": ["It can influence perceived quality, desirability and buyer confidence, although it is only one factor among many", "It fixes the value of every yacht the yard has built", "It has no effect on how the market sees a yacht", "It replaces the need for a survey"], "correct": 0}, {"q": "Why is asking price not the same as market value?", "opts": ["Asking price is always lower than value", "Market value is set by the seller's broker alone", "They are the same once a yacht is listed", "Asking price is what the seller is seeking; value depends on evidence, comparables, condition, specification and demand"], "correct": 3}, {"q": "Which of these are all valid reasons someone might buy a yacht?", "opts": ["Tax reasons, boredom and peer pressure only", "Lifestyle, family use, entertainment, adventure, privacy, passion, exploration or customisation", "Only status and investment return", "Only to charter it to others"], "correct": 1}, {"q": "Which of these are all valid reasons someone might sell a yacht?", "opts": ["Only that the yacht has technical problems", "Only that the owner needs money", "Changing circumstances, upgrading, downsizing, reduced use, a new build arriving or simply deciding to move on", "Only that the yacht is too old"], "correct": 2}, {"q": "Why are comparable yachts important when analysing price?", "opts": ["They provide market evidence and help explain whether price differences are supported by meaningful differences between yachts", "They tell you exactly what a yacht will sell for", "They allow you to ignore condition and specification", "They make surveys unnecessary"], "correct": 0}, {"q": "If information is missing during your research, what should you do?", "opts": ["Fill the gap with the most likely figure", "Leave it out of your analysis entirely", "Assume it matches the other yachts in the comparison", "Identify it as something that needs to be verified, and never turn an assumption into a fact"], "correct": 3}]$json$;
begin
  select id into v_module from public.academy_modules where track = 'yachts' and module_number = 3;
  if v_module is null then
    raise exception 'Yachts module 3 not found';
  end if;

  update public.academy_modules
     set title = 'The Yacht Market', description = 'How does this business actually work?'
   where id = v_module;

  delete from public.academy_module_pages where module_id = v_module;
  delete from public.academy_quiz_questions where module_id = v_module;

  for rec in select * from jsonb_array_elements(v_pages) loop
    n := n + 1;
    if rec ? 'exercise' then
      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id, exercise)
      values (v_module, n, rec->>'heading', rec->>'body', null, rec->'exercise');
    else
      insert into public.academy_quiz_questions (module_id, question_text, order_index, stage, page_number)
      values (v_module, rec->>'q', 0, 'checkpoint', n)
      returning id into v_q;

      for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
        insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
        values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
      end loop;

      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id)
      values (v_module, n, rec->>'heading', rec->>'body', v_q);
    end if;
  end loop;

  n := 0;
  for rec in select * from jsonb_array_elements(v_final) loop
    n := n + 1;
    insert into public.academy_quiz_questions (module_id, question_text, order_index, stage)
    values (v_module, rec->>'q', n - 1, 'final')
    returning id into v_q;

    for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
      insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
      values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
    end loop;
  end loop;
end
$mig$;
